import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

tanh_scale_bias_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void tanh_scale_bias_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float scale,
    int N,
    int C,
    int H,
    int W) 
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * C * H * W;
    if (idx < total_size) {
        float val = input[idx];
        float t = tanhf(val);
        int c = (idx / (H * W)) % C;
        output[idx] = t * scale + bias[c];
    }
}

torch::Tensor tanh_scale_bias_cuda(torch::Tensor x, torch::Tensor bias, float scale) {
    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);

    auto output = torch::zeros_like(x);

    int total_size = N * C * H * W;
    const int block_size = 256;
    const int num_blocks = (total_size + block_size - 1) / block_size;

    tanh_scale_bias_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        scale,
        N,
        C,
        H,
        W
    );

    return output;
}
"""

tanh_scale_bias_cpp_source = r"""
torch::Tensor tanh_scale_bias_cuda(torch::Tensor x, torch::Tensor bias, float scale);
"""

tanh_scale_bias = load_inline(
    name="tanh_scale_bias",
    cpp_sources=tanh_scale_bias_cpp_source,
    cuda_sources=tanh_scale_bias_source,
    functions=["tanh_scale_bias_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape, pool_kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.scaling_factor = scaling_factor
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.max_pool = nn.MaxPool2d(pool_kernel_size)
        self.tanh_scale_bias = tanh_scale_bias

    def forward(self, x):
        x = self.conv(x)
        x = self.tanh_scale_bias.tanh_scale_bias_cuda(x, self.bias, self.scaling_factor)
        x = self.max_pool(x)
        return x
